use relay.feed;

pub fn publish(io: Io) -> Result<Unit, Error> uses {Io.write} {
    let frame_list = feed.frames();
    var total = 0;
    var i = 0;
    while i < frame_list.len() {
        let value = match frame_list.get(index: i) {
            Some(frame) => match feed.decode(frame: frame) {
                Ok(n) => n,
                Err(_) => 0,
            },
            None => 0,
        };
        total = total + value;
        i = i + 1;
    }
    feed.emit(io: io, total: total)?;
    return Ok(unit);
}

