use harbor.signal;

pub fn entries() -> String {
    let signals = harbor.signal.sequence();
    var parts: List<String> = [];
    var i = 0;
    while i < signals.len() {
        let piece = match signals.get(i) {
            Some(s) => match s {
                Calm => "calm",
                Gale(speed) => "gale:".concat(other: speed.to_text()),
                Fog(density) => "fog:".concat(other: density),
            },
            None => "",
        };
        parts.push(item: piece);
        i = i + 1;
    }
    parts.join(sep: ";")
}
